package com.keepcalm.placementportal.service;import com.keepcalm.placementportal.api.PagedResponse;import com.keepcalm.placementportal.entity.*;import com.keepcalm.placementportal.exception.DomainException;import com.keepcalm.placementportal.models.communication.CommunicationDtos.NotificationDto;import com.keepcalm.placementportal.repository.NotificationRepository;import lombok.RequiredArgsConstructor;import org.springframework.cache.annotation.CacheEvict;import org.springframework.cache.annotation.Cacheable;import org.springframework.data.domain.Pageable;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.Map;
@Service @RequiredArgsConstructor public class NotificationService{private final NotificationRepository notifications;private final CurrentUserService current;@CacheEvict(cacheNames="notification-unread",allEntries=true) @Transactional public void notify(User user,String title,String message,String type,String link){Notification n=new Notification();n.setUser(user);n.setTitle(title);n.setMessage(message);n.setType(type);n.setLinkUrl(link);notifications.save(n);}@Transactional(readOnly=true)public PagedResponse<NotificationDto> list(Pageable p){return PagedResponse.from(notifications.findByUserId(current.principal().userId(),p).map(this::dto));}@Cacheable(cacheNames="notification-unread",keyGenerator="userAwareKeyGenerator",sync=true) @Transactional(readOnly=true)public Map<String,Long> unread(){return Map.of("count",notifications.countByUserIdAndReadAtIsNull(current.principal().userId()));}@CacheEvict(cacheNames="notification-unread",allEntries=true) @Transactional public NotificationDto read(Long id){Notification n=notifications.findByIdAndUserId(id,current.principal().userId()).orElseThrow(()->DomainException.notFound("Notification not found"));if(n.getReadAt()==null)n.setReadAt(Instant.now());return dto(n);}@CacheEvict(cacheNames="notification-unread",allEntries=true) @Transactional public Map<String,Integer> readAll(){return Map.of("updated",notifications.markAllRead(current.principal().userId(),Instant.now()));}private NotificationDto dto(Notification n){return new NotificationDto(n.getId(),n.getTitle(),n.getMessage(),n.getType(),n.getLinkUrl(),n.getReadAt(),n.getCreatedAt());}}
